        1, BinaryTree::new(2, BinaryTree::empty(), BinaryTree::leaf(3)), BinaryTree::leaf(4),
    );
    let zipper = Zipper::from_tree(initial_tree)?;
    assert_eq!(@3, zipper.left()?.right()?.value());
    Option::Some(())
}

